import React from 'react';
import { useLocation } from 'react-router-dom';
import { listings } from '../list'; // Adjust the path as necessary

function SearchResults() {
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const query = searchParams.get('query')?.toLowerCase() || '';

  // Filter listings based on the search query
  const filteredListings = Object.entries(listings).flatMap(([category, items]) =>
    items.filter(
      (item) =>
        item.title.toLowerCase().includes(query) ||
        item.location.toLowerCase().includes(query) ||
        category.toLowerCase().includes(query)
    )
  );

  return (
    <div className="container mx-auto px-4 py-6">
      <h1 className="text-2xl font-semibold mb-4">Search Results for "{query}"</h1>
      {filteredListings.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredListings.map((listing) => (
            <div key={listing.id} className="border rounded-md shadow-lg overflow-hidden relative">
              {/* Elite Badge */}
              <div className="absolute top-2 left-2 bg-yellow-400 text-white text-xs font-bold px-2 py-1 rounded">
                Elite
              </div>
              <img
                src={listing.image}
                alt={listing.title}
                className="w-full h-48 object-cover"
              />
              <div className="p-4">
                <h2 className="text-lg font-medium truncate">{listing.title}</h2>
                <p className="text-red-600 font-semibold text-xl">{listing.price}</p>
                <p className="text-gray-500 text-sm">{listing.location}</p>
              </div>
              <div className="p-4 border-t flex justify-between">
                <button className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 text-sm">
                  Call
                </button>
                <button className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600 text-sm">
                  WhatsApp
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <p className="text-gray-500">No results found for "{query}".</p>
      )}
    </div>
  );
}

export default SearchResults;
